module Decoder(
  input  [15:0] dec_req_bits,
  input         dec_req_valid,
  output        dec_req_ready,
  output [15:0] dec_resp_bits_address,
  output        dec_resp_bits_port,
                dec_resp_valid,
  input         dec_resp_ready
);

  wire transform0_decoded = (|(dec_req_bits[15:9])) & dec_req_bits < 16'h400;
  assign dec_req_ready = dec_resp_ready;
  assign dec_resp_bits_address =
    transform0_decoded ? dec_req_bits - 16'h200 : dec_req_bits;
  assign dec_resp_bits_port = transform0_decoded;
  assign dec_resp_valid = dec_req_valid;
endmodule

module Decoder_2(
  input  [15:0] dec_req_bits,
  input         dec_req_valid,
  output        dec_req_ready,
  output [15:0] dec_resp_bits_address,
  output        dec_resp_bits_port,
                dec_resp_valid,
  input         dec_resp_ready
);

  wire transform0_decoded = (|(dec_req_bits[15:10])) & dec_req_bits < 16'h800;
  assign dec_req_ready = dec_resp_ready;
  assign dec_resp_bits_address =
    transform0_decoded ? dec_req_bits - 16'h400 : dec_req_bits;
  assign dec_resp_bits_port = transform0_decoded;
  assign dec_resp_valid = dec_req_valid;
endmodule

module Decoder_4(
  input  [15:0] dec_req_bits,
  input         dec_req_valid,
  output        dec_req_ready,
  output [15:0] dec_resp_bits_address,
  output        dec_resp_bits_port,
                dec_resp_valid,
  input         dec_resp_ready
);

  wire _transform0_T_2 = (|(dec_req_bits[15:11])) & dec_req_bits < 16'h880;
  wire _transform0_T_3 = dec_req_bits > 16'hBFF & dec_req_bits < 16'h1000;
  assign dec_req_ready = dec_resp_ready;
  assign dec_resp_bits_address =
    _transform0_T_3
      ? dec_req_bits - 16'h800
      : _transform0_T_2 ? dec_req_bits - 16'h800 : dec_req_bits;
  assign dec_resp_bits_port = _transform0_T_3 | _transform0_T_2;
  assign dec_resp_valid = dec_req_valid;
endmodule

